(function(){"use strict";function googleUrl(frame){try{var url=new URL(frame.getAttribute("src")||"",location.href);return/^(www\.)?google\.com$|^maps\.google\.com$/.test(url.hostname)&&/^\/maps(?:\/|$)/.test(url.pathname)?url.href:""}catch(_){return""}}function retry(frame){var url=googleUrl(frame);if(!url)return;var fresh=frame.cloneNode(false);fresh.removeAttribute("data-google-recovery");fresh.loading="eager";frame.replaceWith(fresh)}window.addEventListener("bali:maps-retry",function(){document.querySelectorAll("iframe").forEach(function(frame){if(googleUrl(frame)&&frame.getBoundingClientRect().height&&!frame.closest("[inert]"))retry(frame)})})})();